{"content": "# Reproduction test for the use_netrc feature (scratch, not part of the repo suite)
from __future__ import absolute_import, division, print_function
__metaclass__ = type

import os
import sys

sys.path.insert(0, '/app/test/units')

import pytest  # noqa: E402

from ansible.module_utils.urls import Request  # noqa: E402

HERE = '/app/test/units/module_utils/urls'


@pytest.fixture
def urlopen_mock(mocker):
    return mocker.patch('ansible.module_utils.urls.urllib_request.urlopen')


@pytest.fixture
def install_opener_mock(mocker):
    return mocker.patch('ansible.module_utils.urls.urllib_request.install_opener')


def test_netrc_used_by_default(urlopen_mock, install_opener_mock, monkeypatch):
    monkeypatch.setenv('NETRC', os.path.join(HERE, 'fixtures/netrc'))
    Request().open('GET', 'http://ansible.com/')
    req = urlopen_mock.call_args[0][0]
    assert req.headers['Authorization'] == b'Basic dXNlcjpwYXNzd2Q='


def test_netrc_ignored_when_use_netrc_false(urlopen_mock, install_opener_mock, monkeypatch):
    monkeypatch.setenv('NETRC', os.path.join(HERE, 'fixtures/netrc'))
    Request().open('GET', 'http://ansible.com/', use_netrc=False)
    req = urlopen_mock.call_args[0][0]
    assert 'Authorization' not in req.headers


def test_netrc_ignored_via_session(urlopen_mock, install_opener_mock, monkeypatch):
    monkeypatch.setenv('NETRC', os.path.join(HERE, 'fixtures/netrc'))
    Request(use_netrc=False).open('GET', 'http://ansible.com/')
    req = urlopen_mock.call_args[0][0]
    assert 'Authorization' not in req.headers


def test_explicit_authorization_header_survives(urlopen_mock, install_opener_mock, monkeypatch):
    monkeypatch.setenv('NETRC', os.path.join(HERE, 'fixtures/netrc'))
    Request().open('GET', 'http://ansible.com/', headers={'Authorization': 'Bearer token'})
    req = urlopen_mock.call_args[0][0]
    assert req.headers['Authorization'] == 'Bearer token'
